"use client";

import React, { useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { cn } from "@/lib/utils";

export interface MotionTickerProps
  extends React.HTMLAttributes<HTMLDivElement> {
  items?: string[];
  velocity?: number;
  direction?: "left" | "right";
  pauseOnHover?: boolean;
}

const DEFAULT_TICKER_ITEMS = [
  "NEXT-GEN MOTION",
  "FLUID SPRING PHYSICS",
  "ACCESSIBLE BY DEFAULT",
  "VIEW TRANSITIONS",
  "DYNAMIC LAYOUTS",
  "INTERRUPTIBLE GESTURES",
];

export function MotionTicker({
  items = DEFAULT_TICKER_ITEMS,
  velocity = 35,
  direction = "left",
  pauseOnHover = true,
  className,
  ...props
}: MotionTickerProps) {
  const [isPaused, setIsPaused] = useState(false);
  const shouldReduceMotion = useReducedMotion();

  const duration = 1200 / velocity;
  const xTranslation = direction === "left" ? ["0%", "-50%"] : ["-50%", "0%"];

  const repeatedItems = [...items, ...items];

  return (
    <div
      data-slot="motion-ticker"
      onMouseEnter={() => pauseOnHover && setIsPaused(true)}
      onMouseLeave={() => pauseOnHover && setIsPaused(false)}
      className={cn(
        "relative flex w-full overflow-hidden whitespace-nowrap select-none py-4 border-y border-neutral-200 dark:border-neutral-800 bg-neutral-50 dark:bg-neutral-900/50",
        className
      )}
      {...props}
    >
      {/* Gradient edge masks */}
      <div className="pointer-events-none absolute inset-y-0 left-0 w-16 bg-gradient-to-r from-neutral-50 dark:from-neutral-950 to-transparent z-10" />
      <div className="pointer-events-none absolute inset-y-0 right-0 w-16 bg-gradient-to-l from-neutral-50 dark:from-neutral-950 to-transparent z-10" />

      <motion.div
        animate={
          shouldReduceMotion || isPaused
            ? {}
            : {
                x: xTranslation,
              }
        }
        transition={{
          duration,
          ease: "linear",
          repeat: Infinity,
        }}
        className="flex items-center gap-8 will-change-transform"
      >
        {repeatedItems.map((text, index) => (
          <div key={index} className="flex items-center gap-8">
            <span className="font-black text-sm uppercase tracking-widest text-neutral-800 dark:text-neutral-200 font-mono">
              {text}
            </span>
            <span className="text-pink-500 font-bold text-xs">✦</span>
          </div>
        ))}
      </motion.div>
    </div>
  );
}
